M('dry_solids',P('濕樣總重 mw=1000 kg；濕基含水率 w=0.30','Wet sample mass mw=1000 kg; wet-basis moisture w=0.30'),'md=mw*(1-w)','1000*(1-0.30)','kg dry solids',P('只將濕基含水率 w 改成 0.40','Change only wet-basis moisture w to 0.40'),'1000*(1-0.40)',P('水和乾固體分別守恆；濕基含水率以總濕重作分母，乾固體重量才能跨不同含水狀態比較。','Track water and dry solids separately; wet-basis moisture uses total wet mass as denominator and dry mass permits comparison across moisture states.'),P('批次代表性樣本，乾燥減重視為水；揮發性物質或結晶水可能使此假設失效。','A representative batch sample with drying loss treated as water; volatile matter or bound water may invalidate the assumption.'),P('保存稱重、乾燥方法及分樣紀錄，對比重複樣並檢查非水揮發損失。','Retain weighing, drying method and subsampling records and compare duplicates while checking non-water volatile loss.'),P('用濕重比較處理前後會把脫水誤認為固體去除。','Comparing wet masses can mistake dewatering for solids removal.'),P('濕樣減重多少就代表固體或污染物被去除多少。','Wet-mass reduction equals the mass of solids or contaminants removed.'))
M('soil_inventory',P('土壤濕重 mw=1000 kg；濕基水分 w=0.30；乾基濃度 Cd=200 mg/kg dry','Wet soil mw=1000 kg; wet-basis moisture w=0.30; dry-basis concentration Cd=200 mg/kg dry'),'mp=mw*(1-w)*Cd/1e6','1000*(1-0.30)*200/1e6','kg contaminant',P('只將乾基濃度 Cd 改成 150 mg/kg dry','Change only dry-basis concentration Cd to 150 mg/kg dry'),'1000*(1-0.30)*150/1e6',P('先把濕土換成乾重，再乘相同乾基分析濃度；mg 污染物最後換算成 kg，避免含水率假造移除量。','Convert wet soil to dry mass before multiplying by matching dry-basis concentration, then convert pollutant mg to kg to avoid moisture-driven apparent removal.'),P('含水率和濃度代表同批土壤，未含洗液或其他出口，分析濃度不是總土壤成分百分比。','Moisture and concentration represent the same soil batch; wash water and other outlets are excluded, and analytical concentration is not bulk component percentage.'),P('同步取含水與化學分析樣，核對乾基標記及 mg/kg 單位，再與全部固液出口比對。','Collect moisture and chemical samples together, verify dry-basis labels and mg/kg units and reconcile all solid and liquid outlets.'),P('將乾基濃度乘濕重會高估污染庫存，且使不同含水批次不可比。','Multiplying dry-basis concentration by wet mass overstates inventory and prevents fair comparison across moisture states.'),P('土壤乾基 mg/kg 可以直接乘未扣水的濕土重量。','Dry-basis soil mg/kg can be multiplied directly by wet soil mass without removing water.'))
M('forming_water',P('乾混料 md=100 kg；假想濕基含水分率 w=0.20','Dry blend md=100 kg; hypothetical wet-basis water fraction w=0.20'),'mw=md*w/(1-w)','100*0.20/(1-0.20)','kg water',P('只將假想 w 改成 0.25','Change only hypothetical w to 0.25'),'100*0.25/(1-0.25)',P('水分率的分母包含新增水，故從乾料反求加水量需除以一減水分率。','The moisture denominator includes added water, so calculating water from dry solids requires division by one minus the water fraction.'),P('乾料起始無水、無反應耗水與蒸發；純質量換算，不是穩定化配方或現場加水建議。','Initially dry solids with no reaction consumption or evaporation; a mass-conversion example, not a stabilization recipe or field water dose.'),P('分開記錄原料自帶水與外加水，量混合後濕乾重量並檢查反應消耗和滲液。','Record inherent and added water separately, measure wet and dry blend masses and check reaction consumption and drainage.'),P('把濕基百分比直接乘乾料重會低估水量。','Multiplying a wet-basis percentage directly by dry mass understates water.'),P('20% 濕基水分必然等於每 100 kg 乾料加 20 kg 水。','Twenty percent wet-basis moisture always means adding 20 kg water per 100 kg dry solids.'))
M('thermal_uncertainty',P('蒸汽質量流率相對標準不確定度 um=0.04；比焓差相對標準不確定度 uh=0.06','Relative standard uncertainty in steam mass flow um=0.04 and specific-enthalpy rise uh=0.06'),'uP=sqrt(um²+uh²)','math.sqrt(0.04**2+0.06**2)','relative standard uncertainty of thermal power',P('只將焓差不確定度 uh 改成 0.03','Change only enthalpy-rise uncertainty uh to 0.03'),'math.sqrt(0.04**2+0.03**2)',P('熱功率 P=mdot*Δh；獨立小誤差時，相對方差近似相加，焓差需由壓力、溫度與狀態資料求得。','Thermal power P=mdot*Δh; relative variances approximately add for independent small errors, and enthalpy rise requires pressure, temperature and state data.'),P('質量流率和焓差相互獨立的一階傳播；若共享感測器或校正則需共變異，不是完整鍋爐效率不確定度。','First-order propagation for independent mass flow and enthalpy rise; shared sensors or calibration require covariance, and this is not total boiler-efficiency uncertainty.'),P('把流量計、壓溫感測與蒸汽表狀態模型的不確定來源分開，核對時間窗與焓基準。','Separate uncertainty from flowmeter, pressure/temperature sensors and steam-state model and check time windows and enthalpy reference.'),P('忽略濕蒸汽狀態或把總焓當焓差會形成系統偏差，重複量測不會自動消除。','Ignoring wet-steam state or substituting absolute enthalpy for enthalpy rise creates systematic bias that repetitions do not remove.'),P('蒸汽流量量得準就能保證回收熱功率也完全準確。','Accurate steam flow alone guarantees fully accurate recovered thermal power.'))
COURSES={}
def C(cid,focus,discipline,sources,units):
    assert len(units)==10,(cid,len(units)); COURSES[cid]=dict(focus=focus,discipline=discipline,sources=sources,units=units)
def U(title,context,model): return dict(title=title,context=context,model=model)

C('b476',P('從廚餘性質、厭氧反應到沼氣與消化液的完整收支','Close the balances from food-waste properties through digestion, biogas and digestate'),'environment-waste',['ad','adresources','warmdocs'],[
U(P('原料驗收與可分解固體','Feed acceptance and degradable solids'),P('先在數位卸料區標出塑膠、骨殼與可分解物；總濕重不能直接作為甲烷產量基準。','At the digital receiving bay, distinguish plastics, shells and biodegradable material; wet mass is not a direct methane-yield basis.'),'fraction'),
U(P('均質槽與含水基準','Equalization and moisture basis'),P('將不同來源廚餘的水與乾固體分開記帳，混合目的是穩定進料而非讓所有批次看起來相同。','Track water and dry solids separately across food-waste sources; equalization stabilizes feed rather than concealing batch differences.'),'dry_solids'),
U(P('有機體積負荷','Organic volumetric loading'),P('把每日進料濃度與泵送量配對，觀察負荷上升是否早於酸累積與產氣變化。','Pair feed concentration with daily pumping and examine whether loading increases precede acid accumulation and gas changes.'),'loading'),
U(P('停留時間與生物量保留','Residence and biomass retention'),P('液體停留與生物量停留可能不同；加入固液分離時，不能只用槽體容積解釋菌群流失。','Hydraulic and biomass residence may differ; with solids separation, vessel volume alone does not explain biomass washout.'),'retention'),
U(P('水解與反應速率辨識','Hydrolysis and rate identification'),P('用封閉教學批次曲線比較易分解與纖維性廚餘，識別傳質限制與生物反應限制。','Compare closed teaching-batch curves for readily degradable and fibrous waste to distinguish mass transfer from biological limitations.'),'decay'),
U(P('揮發性固體與甲烷產率','Volatile solids and methane yield'),P('在氣體視窗分開顯示總沼氣與甲烷，並將產量回溯到實際破壞的固體。','Display total biogas separately from methane and relate yield to solids actually destroyed.'),'gas_yield'),
U(P('沼氣能量與輔機邊界','Biogas energy and auxiliary boundary'),P('將氣體淨化、儲氣和發電串聯；含硫與水分的處理需保留獨立設備與性能證據。','Connect gas conditioning, storage and generation; sulfur and moisture removal require distinct equipment and performance evidence.'),'gas_energy'),
U(P('消化液殘餘負荷','Residual digestate load'),P('消化液仍攜帶營養鹽與未轉換有機物；必須追蹤去向，不能將產氣視為所有污染已消失。','Digestate still carries nutrients and unconverted organics; track its destination rather than equating gas production with complete pollutant removal.'),'massflow'),
U(P('進料中斷與備援重播','Feed interruption and backup replay'),P('在模擬時間線中重播泵故障，分開記錄停止進料、暫存需求和氣體處理的持續需求。','Replay a feed-pump failure and separately log feed interruption, storage demand and continuing gas-handling needs.'),'availability'),
U(P('物質能量收支驗證','Mass-energy balance verification'),P('交付同一時間窗的進料、消化液與氣體清單，找出最影響碳收支閉合的不確定來源。','Deliver feed, digestate and gas inventories over one interval and identify the uncertainty dominating carbon-balance closure.'),'uncertainty')])

C('b477',P('密閉堆肥的混料、供氧、散熱與成熟度證據','Blend, oxygenate, cool and verify maturation in enclosed composting'),'environment-waste',['compost','odor','warmdocs'],[
U(P('可堆肥物與雜質驗收','Compostable feed and contamination'),P('進料分選須辨認可分解有機物與不屬於堆肥產品的雜質，粉碎不等於去除污染。','Receiving inspection separates compostable organics from product contaminants; shredding does not remove contamination.'),'fraction'),
U(P('碳氮總量配料','Carbon-nitrogen blend accounting'),P('將木質調理料與含氮廚餘逐批分析；總碳氮比需與實際可利用碳一起解讀。','Analyze woody bulking material and nitrogen-rich food waste by batch; interpret total C:N alongside available carbon.'),'cn'),
U(P('含水率混合設計','Moisture blending'),P('濕料提供水分但可能壓縮通氣空間，調理料需求應由水收支與孔隙共同決定。','Wet feed supplies moisture but may restrict aeration; select bulking demand from both water balance and porosity.'),'moisture'),
U(P('填料孔隙與壓實','Bed porosity and compaction'),P('在反應器剖面觀察壓實層；相同風量下，不同堆積狀態產生不同氧分布。','Inspect compacted layers in a reactor section; equal air supply gives different oxygen distributions for different packing.'),'porosity'),
U(P('需氧與送風分配','Oxygen demand and air distribution'),P('把微生物需氧量與送風網路連結，利用區域讀值尋找缺氧口袋。','Link microbial oxygen demand to the air network and use zone readings to locate oxygen-depleted pockets.'),'oxygen'),
U(P('生物熱與顯熱移除','Biological heat and sensible cooling'),P('堆體自行產熱，出風帶走熱量；溫度控制需兼顧反應速率與過度冷卻。','The pile generates heat while exhaust removes it; temperature control balances reaction and excessive cooling.'),'sensible'),
U(P('蒸發損失與補水','Evaporation and water replacement'),P('將濕度與質量減少對照，區分蒸發造成的乾燥和生物分解造成的有機物減少。','Compare humidity with weight loss to distinguish evaporation-driven drying from biological organic-matter loss.'),'evaporation'),
U(P('批次停留與短流','Batch residence and short-circuiting'),P('連續進料設備須追蹤物料停留分布；平均時間不能證明每份物料都經歷相同條件。','Continuous reactors need material residence distributions; a mean duration does not prove identical histories for every portion.'),'retention'),
U(P('熟化速率與穩定度','Curing rate and stability'),P('熟化曲線需配合呼吸活性與再升溫觀察；一次低溫讀值可能只是乾燥或缺氧。','Interpret curing curves with respiration and reheating observations; one low-temperature reading may reflect dryness or oxygen shortage.'),'decay'),
U(P('密閉系統與故障交接','Enclosure failure and handoff'),P('重播風機停機與排氣處理失效，在教學儀表上記錄可用時間和產品批次隔離。','Replay fan or exhaust-treatment failure and document availability and affected batch segregation in the teaching interface.'),'availability')])

C('b478',P('用空間氧氣、水分與溫度資料調整條垛堆肥通風','Use spatial oxygen, moisture and temperature evidence to assess windrow aeration'),'environment-waste',['compost','odor','warmdocs'],[
U(P('條垛原料碳氮分層','Windrow carbon-nitrogen heterogeneity'),P('條垛不是均質容器，混料紀錄應保留各區原料比例，避免平均比值掩蓋局部差異。','A windrow is not a homogeneous vessel; retain local blend records so averages do not conceal heterogeneity.'),'cn'),
U(P('雨後含水調整','Moisture after rainfall'),P('雨水可增加表層含水，核心仍可能偏乾；採樣位置需隨深度記錄。','Rain wets surface layers while cores may remain dry; record sampling depth and position.'),'moisture'),
U(P('翻堆與可通氣孔隙','Turning and aeratable porosity'),P('翻堆會重新配置顆粒與孔隙，改善暫時配流但不能代替後續氧氣監測。','Turning rearranges particles and pores, temporarily improving distribution without replacing subsequent oxygen monitoring.'),'porosity'),
U(P('需氧估計與區域供氣','Oxygen estimation and zoned air'),P('比較表層、核心與底部的氧濃度，辨認供氣量不足和氣流繞行兩種原因。','Compare surface, core and base oxygen to distinguish insufficient supply from bypass flow.'),'oxygen'),
U(P('強制通風能耗','Forced-aeration energy'),P('調整送風時同時看風機功率和氧氣分布，避免把高電耗當成高處理能力。','When changing aeration, examine both fan power and oxygen distribution rather than equating power with treatment capacity.'),'blower'),
U(P('配氣管與堆體阻力','Distribution pipes and pile resistance'),P('在主管與分支量差壓，分辨管路堵塞和堆體局部壓實。','Measure main-header and branch differentials to distinguish duct blockage from local pile compaction.'),'pressure'),
U(P('冬夏顯熱交換','Seasonal sensible-heat exchange'),P('相同送風量在不同氣溫下有不同冷卻能力，通風策略需保留氣象條件。','Equal airflow has different cooling effects at different ambient temperatures, so retain meteorological conditions.'),'sensible'),
U(P('通風乾燥與蒸發','Ventilation drying and evaporation'),P('高風量可能快速帶走水分而抑制反應，不能只以溫度下降當成改善。','High airflow can remove moisture and inhibit activity; cooling alone is not evidence of improvement.'),'evaporation'),
U(P('露天雨水與滲出水收支','Outdoor rainfall and leachate balance'),P('把條垛場地逕流、蓄水與滲出液分開，避免雨量直接轉成污染水量。','Separate runoff, storage and leachate across the windrow pad instead of converting all rainfall directly into contaminated drainage.'),'rain_balance'),
U(P('空間監測與缺測管理','Spatial monitoring and missingness'),P('感測器失聯可能集中在高溫潮濕區；保留地點和時間缺測圖，再評估通風一致性。','Sensor outages may cluster in hot, wet zones; retain spatial and temporal gap maps before evaluating aeration uniformity.'),'coverage')])

C('b479',P('以熱量、料床停留與排放證據理解爐排燃燒控制','Understand grate combustion through heat input, bed residence and emission evidence'),'environment-waste',['wi','wiindex','control'],[
U(P('垃圾熱值與負荷邊界','Waste heating value and load boundary'),P('將濕基進料、含水率及熱值連結，從源頭解釋蒸汽與煙氣波動。','Link wet feed, moisture and heating value to explain steam and flue-gas fluctuations at the source.'),'fuelheat'),
U(P('一次與二次空氣的功能','Primary and secondary air roles'),P('一次空氣穿過料床，二次空氣協助氣相混合；總量與分配必須分開評估。','Primary air passes through the bed while secondary air supports gas mixing; assess totals separately from distribution.'),'airratio'),
U(P('爐排速度與物料停留','Grate motion and material residence'),P('以動畫追蹤乾燥、燃燒與燃盡區，料床厚度和滑移會改變實際停留。','Track drying, combustion and burnout zones in animation; bed depth and slip alter actual residence.'),'belt_time'),
U(P('含水進料的熱需求','Heating demand of wet feed'),P('高含水垃圾先消耗熱量升溫，並增加後續蒸發負荷，不能直接視為有效燃料。','Wet waste first absorbs sensible heat and adds evaporation demand; it is not all useful fuel.'),'sensible'),
U(P('煙氣污染質量通量','Flue-gas pollutant mass rate'),P('將濃度與同基準氣量組合，辨認稀釋變化和真正污染負荷變化。','Combine concentration with matched gas flow to distinguish dilution from pollutant-load changes.'),'gas_mass'),
U(P('氧校正與比較基準','Oxygen normalization and comparison'),P('在數位報表分開顯示原始與校正濃度，避免配風改變引起的表面改善。','Show raw and normalized concentrations separately to avoid apparent improvement caused only by airflow changes.'),'oxygen_correction'),
U(P('整合煙氣處理績效','Integrated flue-gas treatment performance'),P('燃燒與末端防制共同影響出口，需比較入口負荷、出口濃度與殘渣去向。','Combustion and downstream control jointly determine discharge; compare inlet loads, outlet levels and residue destinations.'),'efficiency'),
U(P('風量阻力與引風','Draft and gas-path resistance'),P('爐膛至煙道的差壓變化可能來自積灰或流量；用兩種訊號區分原因。','Pressure-drop changes along the furnace-to-stack path may reflect deposits or flow; distinguish causes with both signals.'),'pressure'),
U(P('毛發電與淨效益','Gross generation and net benefit'),P('燃燒最佳化須連同引風、送風與加藥輔機用電評估，不能只最大化蒸汽量。','Evaluate combustion together with draft, air and dosing auxiliaries rather than maximizing steam alone.'),'netpower'),
U(P('異常事件重播與可用率','Upset replay and availability'),P('在離線模型重播進料突然改變，追蹤警報先後與恢復過程；不傳送任何真實設備指令。','Replay abrupt feed changes offline and trace alarm order and recovery; no real equipment commands are transmitted.'),'availability')])

C('b480',P('連結焚化熱輸入、傳熱阻力與蒸汽循環的能量平衡','Connect incinerator heat input, thermal resistance and the steam cycle'),'environment-waste',['wi','control','wiindex'],[
U(P('焚化熱輸入基準','Incineration heat-input basis'),P('先固定濕基低位熱值與進料時間窗，再討論鍋爐的熱回收比例。','Fix wet-basis lower heating value and feed interval before discussing boiler heat recovery.'),'fuelheat'),
U(P('煙氣顯熱曲線','Flue-gas sensible-heat curve'),P('用各受熱面前後溫度建立能量梯度，辨認熱量移除的主要區段。','Use temperatures across heating surfaces to map energy gradients and identify major heat-removal sections.'),'sensible'),
U(P('給水與蒸汽焓差','Feedwater-to-steam enthalpy rise'),P('過熱、汽化與給水加熱需以焓統一計算，不能只比溫度。','Unify superheating, vaporization and feedwater heating through enthalpy rather than temperature alone.'),'steam'),
U(P('積灰造成的總熱阻','Overall resistance from deposits'),P('比較清潔與積灰工況的有效傳熱係數，並將煙氣溫度變化與熱值變動分開。','Compare effective coefficients for clean and fouled conditions, separating gas-temperature changes from fuel variations.'),'ua'),
U(P('煙側差壓與堵塞診斷','Gas-side pressure drop and blockage'),P('熱傳下降與差壓上升同時出現，較能支持積灰假說；單一訊號不足以確診。','Concurrent heat-transfer decline and pressure-drop rise better support fouling than either signal alone.'),'pressure'),
U(P('進料水分的潛熱代價','Latent-heat cost of feed moisture'),P('原料中的水分隨排氣離開時攜帶能量，冷凝回收情境須另處理腐蝕與水質。','Water leaving with exhaust carries energy; condensing-recovery scenarios require separate corrosion and water-quality treatment.'),'evaporation'),
U(P('循環泵與給水輔機','Circulation and feedwater auxiliaries'),P('把泵送揚程與流量連回循環需求，避免淨發電評估遺漏輔機。','Relate pumping head and flow to cycle demand so net-generation assessment includes auxiliaries.'),'pump'),
U(P('淨電力與熱利用邊界','Net electricity and useful-heat boundary'),P('發電、供熱與廠內自用要分項記帳，聯產效率不能重複計入。','Account separately for electricity, useful heat and internal consumption without double-counting cogeneration.'),'netpower'),
U(P('量測誤差與能量閉合','Measurement error and energy closure'),P('同時核對燃料熱輸入、蒸汽流量和焓差，找出能量殘差是否超過量測不確定度。','Reconcile fuel heat, steam flow and enthalpy rise and test whether the residual exceeds measurement uncertainty.'),'thermal_uncertainty'),
U(P('清灰維護與長期產能','Cleaning maintenance and long-term output'),P('比較延後維護造成的降額和安排停機時間，將單日高產量放回年度尺度。','Compare derating from delayed maintenance with planned downtime and place daily output in an annual context.'),'availability')])

def calc(expression):
    tree=ast.parse(expression,mode='eval')
    allowed=(ast.Expression,ast.BinOp,ast.UnaryOp,ast.Constant,ast.Add,ast.Sub,ast.Mult,ast.Div,ast.Pow,ast.USub,ast.UAdd,ast.Load,ast.Call,ast.Attribute,ast.Name)
    for node in ast.walk(tree):
        if not isinstance(node,allowed): raise ValueError(expression)
        if isinstance(node,ast.Name) and node.id!='math': raise ValueError(expression)
        if isinstance(node,ast.Attribute) and (not isinstance(node.value,ast.Name) or node.value.id!='math' or node.attr not in ('exp','sqrt','log10','ceil','pi')): raise ValueError(expression)
    return eval(compile(tree,'<authored numerical example>','eval'),{'__builtins__':{},'math':math},{})

def emit():
    for datafile in sorted(HERE.glob('group_*.py')):
        exec(compile(datafile.read_text(encoding='utf-8'),str(datafile),'exec'),globals())
    report={'courseCount':len(COURSES),'units':0,'checks':0,'courseIds':[],'sourcePolicy':'Primary institutional sources, verified by web retrieval 2026-10-23; original teaching models and hypothetical inputs; no claimed operational settings.'}
    for cid,raw in sorted(COURSES.items()):
        target=TARGETS[cid]; units=[]; checks=[]
        for j,u in enumerate(raw['units'],1):
            model=MODELS[u['model']]; expected=calc(model['expression']); changed=calc(model['changed_expression'])
            assert math.isfinite(expected) and math.isfinite(changed)
            title=S(u['title']); context=S(u['context']); physical=S(model['physics']); inputs=S(model['inputs']); bounds=S(model['boundary']); verify=S(model['verify']); failure=S(model['failure']); change=S(model['change'])
            def fmt(n): return str(int(n)) if abs(n-round(n))<1e-10 else f'{n:.6g}'
            out={
              'title':u['title'],
              'mechanism':P(context[0]+' '+physical[0],context[1]+' '+physical[1]),
              'model':P('原創教學假設，非現場操作值：'+inputs[0]+'。公式 '+model['formula']+'，計算得 '+fmt(expected)+' '+model['unit']+'。適用邊界：'+bounds[0], 'Original teaching assumptions, not field operating values: '+inputs[1]+'. Formula '+model['formula']+' gives '+fmt(expected)+' '+model['unit']+'. Applicability: '+bounds[1]),
              'verify':P('針對「'+title[0]+'」，'+verify[0]+' 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。','For '+title[1]+', '+verify[1]+' Retain raw data, units and calibration date; compare the model with one alternative explanation.'),
              'failure':P(failure[0]+' 在「'+title[0]+'」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。',failure[1]+' Mark where this error can enter the '+title[1]+' flow and name a measurement that distinguishes causes.'),
              'misconception':model['wrong'],
              'practice':P(change[0]+'，其餘輸入固定。重算結果應由 '+fmt(expected)+' 變成 '+fmt(changed)+' '+model['unit']+'。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。',change[1]+', holding all other inputs fixed. Recalculation changes '+fmt(expected)+' to '+fmt(changed)+' '+model['unit']+'. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.'),
              'modelType':u['model']
            }
            assert all('~' in out[k] for k in ('title','mechanism','model','verify','failure','misconception','practice'))
            units.append(out)
            for variant,expr,result in [('baseline',model['expression'],expected),('sensitivity',model['changed_expression'],changed)]:
                checks.append({'expression':expr.replace('math.',''),'expected':result,'unit':model['unit'],'description':cid+' unit '+str(j)+' '+variant+': '+title[1],'relativeTolerance':1e-9})
        sources=[{'id':'v17s-waste-'+key,'title':SOURCES[key][0],'titleEn':SOURCES[key][1],'url':SOURCES[key][2],'organization':SOURCES[key][3],'accessed':'2026-10-23'} for key in raw['sources']]
        focus=S(raw['focus']); progression='、'.join(S(u['title'])[0] for u in raw['units'][::2]); progression_en=', '.join(S(u['title'])[1] for u in raw['units'][::2])
        doc={'id':cid,'title':P(target['title'],target['titleEn']),'focus':raw['focus'],'discipline':raw['discipline'],
          'summary':P('本課以「'+focus[0]+'」為主軸，依序處理'+progression+'。十個單元各包含機制、算例、量測驗證及失效診斷；數值均為明示的原創教學假設，不能直接用作工程設計、排放限值或設備設定。','This course focuses on '+focus[1]+', progressing through '+progression_en+'. Ten units each address mechanism, worked calculation, measurement verification and failure diagnosis. Numbers are explicit original teaching assumptions, not design values, emission limits or equipment settings.'),
          'history':P('這項技術的學習脈絡由單一設備處理，逐步擴展至物質與能量收支、監測品質和生命週期比較。本課將官方方法文件作為查核入口，並以獨立編寫的假想數據練習；參考文件的年代與地區不代表其規範在所有場址適用。','The learning progression expands from individual treatment equipment to mass and energy balances, monitoring quality and lifecycle comparison. Official method documents provide verification starting points while independently authored hypothetical data support practice; a document date or jurisdiction does not establish applicability to every site.'),
          'place':{'name':'教學參考區域：美國北卡羅來納研究三角園區（非本課實拍場址）','nameEn':'Reference region: Research Triangle Park, North Carolina (not a photographed course facility)','country':'美國','countryEn':'United States','lat':35.9,'lon':-78.9,'scope':'Approximate institutional reference region; not a facility entrance, installation location or visitor permission.'},
          'architectureNodes':[u['title'] for u in raw['units'][::2]]+[P('證據與交接','Evidence and handoff')],
          'sources':sources,'units':units,'modelChecks':checks,
          'facts':[P('所有算例的輸入均為教學假設；官方來源支援方法脈絡，不代表其公開數據。','All numerical inputs are teaching assumptions; official sources support methodological context, not those hypothetical observations.'),P('原始資料、單位、時間窗與不確定度必須一併保存。','Preserve raw data, units, time windows and uncertainty together.')]}
        path=BASE/'inputs'/f'{cid}.json';path.write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        report['units']+=len(units);report['checks']+=len(checks);report['courseIds'].append(cid)
    (HERE/'validation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (HERE/'sources_verified.json').write_text(json.dumps({'accessed':'2026-10-23','sources':[{'key':k,'title':v[1],'url':v[2],'organization':v[3]} for k,v in SOURCES.items()]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(report,ensure_ascii=False))

if __name__=='__main__': emit()

